<script setup lang="ts">import{reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{useAuthStore}from'../store/auth';const loginMode=ref(true),loading=ref(false),form=reactive({username:'',email:'',password:''}),auth=useAuthStore(),router=useRouter(),route=useRoute();async function submit(){loading.value=true;try{loginMode.value?await auth.login(form):await auth.register(form);router.push(String(route.query.redirect||'/create'))}finally{loading.value=false}}</script>
<template><main class="auth-page"><section class="auth-art"><div class="auth-brand"><span class="brand-mark"><i></i><i></i><i></i></span><b>声序</b></div><div class="auth-copy"><span>AI MUSIC WORKSPACE</span><h1>把脑海里的声音，<br/>变成下一首歌。</h1><p>描述一种情绪、一段场景，剩下的交给声序。</p></div></section><section class="auth-form"><div class="form-wrap"><small>欢迎来到声序</small><h2>{{loginMode?'继续你的创作':'创建创作者账户'}}</h2><p>{{loginMode?'还没有账户？':'已经有账户？'}} <button class="link" @click="loginMode=!loginMode">{{loginMode?'立即注册':'返回登录'}}</button></p><el-form label-position="top" @submit.prevent="submit"><el-form-item v-if="!loginMode" label="用户名"><el-input v-model="form.username" minlength="2" maxlength="40" placeholder="你的创作者名称"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email" type="email" placeholder="name@example.com"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" show-password placeholder="至少 8 位字符"/></el-form-item><el-button class="auth-submit" native-type="submit" type="primary" size="large" :loading="loading" :disabled="!form.email||form.password.length<8||(!loginMode&&!form.username)">{{loginMode?'登录':'创建账户'}}</el-button></el-form><p class="fineprint">继续即表示你同意合理使用 AI 音乐服务。</p></div></section></main></template>
